#[path = "solution.rs"]
mod solution;

use solution::{aggregate_readings, AggregateError, Reading};

#[test]
fn sums_matching_readings_and_owns_the_result_kind() {
    let readings = vec![
        Reading { value: 4, kind: "bytes".to_owned() },
        Reading { value: 9, kind: "bytes".to_owned() },
    ];

    let result = aggregate_readings(&readings, "bytes").unwrap();
    assert_eq!(result.value, 13);
    assert_eq!(result.kind, "bytes");
    assert_eq!(readings[0].value, 4);
    assert_eq!(readings[0].kind, "bytes");
    assert_eq!(readings[1].kind, "bytes");
}

#[test]
fn empty_input_and_empty_matching_kind_are_valid() {
    let empty = aggregate_readings(&[], "").unwrap();
    assert_eq!(empty.value, 0);
    assert_eq!(empty.kind, "");

    let readings = vec![Reading { value: 7, kind: String::new() }];
    let result = aggregate_readings(&readings, "").unwrap();
    assert_eq!(result.value, 7);
    assert_eq!(result.kind, "");
}

#[test]
fn reports_the_first_mismatching_kind_in_input_order() {
    let readings = vec![
        Reading { value: 1, kind: "wanted".to_owned() },
        Reading { value: 2, kind: "first-wrong".to_owned() },
        Reading { value: 3, kind: "second-wrong".to_owned() },
    ];

    match aggregate_readings(&readings, "wanted") {
        Err(AggregateError::UnexpectedKind { expected, found }) => {
            assert_eq!(expected, "wanted");
            assert_eq!(found, "first-wrong");
        }
        _ => panic!("expected the first kind mismatch"),
    }

    assert_eq!(readings[1].kind, "first-wrong");
}

#[test]
fn detects_u128_overflow_without_wrapping_or_saturating() {
    let readings = vec![
        Reading { value: u128::MAX, kind: "n".to_owned() },
        Reading { value: 1, kind: "n".to_owned() },
    ];

    assert!(matches!(
        aggregate_readings(&readings, "n"),
        Err(AggregateError::Overflow)
    ));
    assert_eq!(readings[0].value, u128::MAX);
    assert_eq!(readings[1].value, 1);
}

#[test]
fn maximum_sum_itself_is_valid() {
    let readings = vec![Reading { value: u128::MAX, kind: "max".to_owned() }];
    let result = aggregate_readings(&readings, "max").unwrap();
    assert_eq!(result.value, u128::MAX);
}

